begin;
select set_config('request.jwt.claim.sub',(select id::text from auth.users limit 1),true);
do $$declare actor uuid=auth.uid();cid uuid=gen_random_uuid();co uuid=gen_random_uuid();sp uuid=gen_random_uuid();svc uuid=gen_random_uuid();site uuid=gen_random_uuid();d1 uuid=gen_random_uuid();d2 uuid=gen_random_uuid();veh uuid=gen_random_uuid();rid uuid=gen_random_uuid();rid2 uuid=gen_random_uuid();shift1 uuid;shift2 uuid;rec jsonb;stamp integer;token text;other_token text;trip uuid;resultid uuid=gen_random_uuid();batch uuid=gen_random_uuid();docs jsonb;original_start timestamptz;original_end timestamptz;runid uuid=gen_random_uuid();photoid uuid=gen_random_uuid();dutyid uuid;expenseid uuid=gen_random_uuid();basecount integer;rowdata jsonb;begin
 if actor is null then raise exception 'TEST: fixture needs an auth user';end if;
 insert into respectlogistic_customers(id,owner_id,inn,payload) values(cid,actor,'9900000000','{"name":"DISPATCH-ROLLBACK","inn":"9900000000"}');
 insert into respectlogistic_contracts(id,owner_id,customer_id,kind,number,date,payload) values(co,actor,cid,'transport','DISPATCH-ROLLBACK-'||co,current_date,'{}');
 insert into respectlogistic_specifications(id,owner_id,customer_id,contract_id,number,date,payload) values(sp,actor,cid,co,'DISPATCH-SPEC-'||sp,current_date,'{}');
 insert into respectlogistic_services(id,owner_id,customer_id,contract_id,specification_id,name,unit,price_kopecks) values(svc,actor,cid,co,sp,'Перевозка','т',12200);
 insert into respectlogistic_sites(id,owner_id,customer_id,contract_id,specification_id,service_id,payload) values(site,actor,cid,co,sp,svc,'{"name":"TEST SITE","routeKm":"10"}');
 insert into crm_drivers(id,owner_id,app_scope,full_name) values(d1,actor,'respectlogistic','DISPATCH DRIVER'),(d2,actor,'respectlogistic','OTHER DRIVER');
 insert into crm_vehicles(id,owner_id,app_scope,plate,assigned_driver_id) values(veh,actor,'respectlogistic','D-'||substr(veh::text,1,8),d2);
 rec=jsonb_build_object('id',rid,'customer_id',cid,'site_id',site,'date_from',current_date,'date_to',current_date+7,'loading_address','LOAD','loading_point','55.7,37.6','unloading_point','Ворота 2','cargo_name','Песок','cargo_mass','По факту','unloading_address','UNLOAD','loading_from','08:00','loading_to','22:00','unloading_from','08:00','unloading_to','22:00','contact_name','TEST','contact_phone','+79990000000','time_zone','UTC');
 perform respectlogistic_save_dispatch(rec);
 if not exists(select 1 from respectlogistic_dispatch_requests where id=rid and payload->>'unloading_point'='Ворота 2' and payload->>'cargo_mass'='По факту' and payload->>'cargo_name'='Песок') then raise exception 'TEST: waybill fields not persisted';end if;
 if exists(select 1 from crm_trips where vehicle_id=veh) then raise exception 'TEST: draft created a trip';end if;
 perform respectlogistic_driver_access(d1,'password','dispatch-'||d1,'temporary-password-123');token=respectlogistic_driver_login('dispatch-'||d1,'temporary-password-123')->>'token';perform respectlogistic_driver_password(token,'permanent-password-456');
 perform respectlogistic_driver_access(d2,'password','dispatch-'||d2,'temporary-password-123');other_token=respectlogistic_driver_login('dispatch-'||d2,'temporary-password-123')->>'token';perform respectlogistic_driver_password(other_token,'permanent-password-456');
 perform respectlogistic_assign_dispatch(rid,1,current_date,current_date+1,jsonb_build_array(jsonb_build_object('vehicle_id',veh,'driver_id',d1)));
 perform respectlogistic_assign_dispatch(rid,1,current_date,current_date+1,jsonb_build_array(jsonb_build_object('vehicle_id',veh,'driver_id',d1)));
 if (select count(*) from respectlogistic_dispatch_shifts where request_id=rid)<>2 then raise exception 'TEST: assignment duplicated';end if;
 select id,version into shift1,stamp from respectlogistic_dispatch_shifts where request_id=rid and shift_date=current_date;
 select id into shift2 from respectlogistic_dispatch_shifts where request_id=rid and shift_date=current_date+1;
 perform respectlogistic_dispatch_action(shift1,stamp,'send');select version into stamp from respectlogistic_dispatch_shifts where id=shift1;
 perform set_config('request.jwt.claim.sub','',true);
 if jsonb_array_length(respectlogistic_driver_dispatch(other_token)->'dispatch_shifts')<>0 then raise exception 'TEST: other driver saw a shift';end if;
 if jsonb_array_length(respectlogistic_driver_dispatch(token)->'dispatch_shifts')<>1 or respectlogistic_driver_dispatch(token)::text like '%unit_price%' then raise exception 'TEST: shift missing or price leaked';end if;
 begin perform respectlogistic_driver_dispatch(other_token,'accept',shift1,stamp);raise exception using message='TEST: foreign driver accepted',errcode='P0002';exception when sqlstate 'P0001' then null;end;
 perform respectlogistic_driver_dispatch(token,'accept',shift1,stamp);
 if exists(select 1 from crm_trips where vehicle_id=veh) then raise exception 'TEST: acceptance created a trip/zero volume';end if;

 select version into stamp from respectlogistic_dispatch_shifts where id=shift1;
 begin perform respectlogistic_driver_mobile(token,'start',jsonb_build_object('id',runid,'shift_id',shift1));raise exception using message='TEST: run without duty',errcode='P0002';exception when sqlstate 'P0001' then null;end;
 dutyid=respectlogistic_duty_action(token,veh,'start',0);
 perform respectlogistic_driver_mobile(token,'start',jsonb_build_object('id',runid,'shift_id',shift1));
 perform respectlogistic_driver_mobile(token,'start',jsonb_build_object('id',runid,'shift_id',shift1));
 if exists(select 1 from crm_trips where vehicle_id=veh) then raise exception 'TEST: start generated financial trip';end if;
 begin perform respectlogistic_driver_mobile(other_token,'stage',jsonb_build_object('id',runid,'stage','loading'));raise exception using message='TEST: foreign run edit',errcode='P0002';exception when sqlstate 'P0001' then null;end;
 begin perform respectlogistic_driver_mobile(token,'stage',jsonb_build_object('id',runid,'stage','unloaded'));raise exception using message='TEST: skipped stage',errcode='P0002';exception when sqlstate 'P0001' then null;end;
 perform respectlogistic_driver_mobile(token,'stage',jsonb_build_object('id',runid,'stage','loading'));
 perform respectlogistic_driver_mobile(token,'stage',jsonb_build_object('id',runid,'stage','unloaded'));
 begin perform respectlogistic_driver_mobile(token,'complete',jsonb_build_object('id',runid,'volume',12.7));raise exception using message='TEST: completion without document',errcode='P0002';exception when sqlstate 'P0001' then null;end;
 perform respectlogistic_driver_mobile(token,'photo',jsonb_build_object('id',photoid,'run_id',runid,'kind','document','file_name','Test.jpg'),'/9j/2Q==');
 select count(*) into basecount from crm_payroll_accruals where owner_id=actor;
 rowdata=respectlogistic_driver_mobile(token,'complete',jsonb_build_object('id',runid,'volume',12.7));trip=(rowdata->>'trip_id')::uuid;
 perform respectlogistic_driver_mobile(token,'complete',jsonb_build_object('id',runid,'volume',12.7));
 begin perform respectlogistic_driver_mobile(token,'complete',jsonb_build_object('id',runid,'volume',13));raise exception using message='TEST: changed completed quantity',errcode='P0002';exception when sqlstate 'P0001' then null;end;
 if (select count(*) from crm_trips where vehicle_id=veh)<>1 or not exists(select 1 from respectlogistic_driver_shift_files where trip_id=trip and id=photoid) then raise exception 'TEST: duplicate trip or missing document';end if;
 if to_regclass('public.rl_crm_payroll_accruals') is not null then
 if (select count(*) from crm_payroll_accruals where owner_id=actor)<>basecount+1 then raise exception 'TEST: payroll did not accrue exactly once';end if;
 end if;
 if jsonb_array_length(respectlogistic_driver_mobile(other_token)->'mobile_runs')<>0 then raise exception 'TEST: foreign driver read run';end if;
 if jsonb_array_length(respectlogistic_driver_mobile(other_token)->'salary')<>0 then raise exception 'TEST: foreign driver salary';end if;
 begin perform respectlogistic_driver_mobile(other_token,'file',jsonb_build_object('id',photoid));raise exception using message='TEST: foreign photo read',errcode='P0002';exception when sqlstate 'P0001' then null;end;
 -- Deleted trips and their files disappear even when a driver keeps an old ID.
 perform set_config('request.jwt.claim.sub',actor::text,true);
 update crm_trips set deleted_at=clock_timestamp() where id=trip;
 perform set_config('request.jwt.claim.sub','',true);
 if exists(select 1 from jsonb_array_elements(respectlogistic_driver_mobile(token)->'mobile_runs') x where x->>'trip_id'=trip::text) then raise exception 'TEST: deleted trip history visible';end if;
 begin perform respectlogistic_driver_mobile(token,'file',jsonb_build_object('id',photoid));raise exception using message='TEST: deleted trip photo accessible',errcode='P0002';exception when sqlstate 'P0001' then null;end;
 begin perform respectlogistic_driver_file(photoid,token);raise exception using message='TEST: deleted legacy photo accessible',errcode='P0002';exception when sqlstate 'P0001' then null;end;
 perform set_config('request.jwt.claim.sub',actor::text,true);
 update crm_trips set deleted_at=null where id=trip;
 update respectlogistic_dispatch_requests set cancelled_at=clock_timestamp() where id=rid;
 perform set_config('request.jwt.claim.sub','',true);
 if jsonb_array_length(respectlogistic_driver_mobile(token)->'mobile_runs')<>0 or jsonb_array_length(respectlogistic_driver_mobile(token)->'mobile_photos')<>0 then raise exception 'TEST: cancelled request history visible';end if;
 perform set_config('request.jwt.claim.sub',actor::text,true);
 update respectlogistic_dispatch_requests set cancelled_at=null where id=rid;
 perform set_config('request.jwt.claim.sub','',true);
 perform respectlogistic_driver_mobile(token,'expense',jsonb_build_object('id',expenseid,'kind','fuel','vehicle_id',veh,'date',current_date,'litres',100,'price',65,'total',6500));
 perform respectlogistic_driver_mobile(token,'photo',jsonb_build_object('id',gen_random_uuid(),'expense_id',expenseid,'kind','receipt'),'/9j/2Q==');
 begin perform respectlogistic_driver_mobile(token,'expense',jsonb_build_object('id',gen_random_uuid(),'kind','fuel','vehicle_id',veh,'date',current_date,'litres',100,'price',65,'total',7000));raise exception using message='TEST: wrong fuel total',errcode='P0002';exception when sqlstate 'P0001' then null;end;
 -- Another run on the same request in the same duty, then breakdown preserves the unfinished run.
 runid=gen_random_uuid();perform respectlogistic_driver_mobile(token,'start',jsonb_build_object('id',runid,'shift_id',shift1));
 begin perform respectlogistic_driver_mobile(token,'end',jsonb_build_object('id',dutyid,'reason','normal','odometer',10,'technical_note','Исправна'));raise exception using message='TEST: normal end during active run',errcode='P0002';exception when sqlstate 'P0001' then null;end;
 perform respectlogistic_driver_mobile(token,'end',jsonb_build_object('id',dutyid,'reason','breakdown','odometer',10,'technical_note','Поломка двигателя'));
 if not exists(select 1 from respectlogistic_mobile_runs where id=runid and stage='interrupted') or not exists(select 1 from respectlogistic_driver_duties where id=dutyid and end_reason='breakdown' and ended_at is not null and technical_note='Поломка двигателя') then raise exception 'TEST: breakdown data lost';end if;
 perform set_config('mobile.test_token',token,true);perform set_config('mobile.test_photo',photoid::text,true);
end$$;
set local role anon;
do $$begin
 if jsonb_array_length(respectlogistic_driver_mobile(current_setting('mobile.test_token'))->'mobile_runs')<>2 then raise exception 'TEST: opaque session list';end if;
 begin perform respectlogistic_driver_mobile();raise exception using message='TEST: unauthenticated access',errcode='P0002';exception when sqlstate '28000' then null;end;
 begin perform count(*) from respectlogistic_mobile_photos;raise exception using message='TEST: direct file read',errcode='P0002';exception when insufficient_privilege then null;end;
end$$;
reset role;
rollback;
select 'PASS: mobile run persistence, ordered stages, documents required, real trip idempotency, single payroll, photo/driver isolation, fuel validation, breakdown and RLS. Rolled back.' as verification;
